from collections.abc import Iterator
import struct
import zlib


class FrameError(Exception):
    """Base class for frame-related errors."""
    pass


class CrcError(FrameError):
    """CRC error in the frame."""
    pass


class VersionError(FrameError):
    """Unknown version in the frame."""
    pass


class SequenceError(FrameError):
    """Sequence number error in the frame."""
    pass


class PayloadError(FrameError):
    """Payload-related errors."""
    pass


class Event:
    """Immutable typed event representing a decoded frame."""

    def __init__(self, stream_id: int, sequence_number: int, payload: bytes):
        self.stream_id = stream_id
        self.sequence_number = sequence_number
        self.payload = payload


class Stats:
    """Statistics for the decoder."""

    def __init__(self):
        self.rejected_frames = 0
        self.decoded_frames = 0


class Config:
    """Configuration for the decoder."""

    def __init__(self, max_frame_size: int=1024 * 1024, max_buffer_size: int=1024 * 1024 * 10):
        self.max_frame_size = max_frame_size
        self.max_buffer_size = max_buffer_size


class Decoder:
    """Decoder for telemetry stream frames."""
    SYNC_MARKER = b'\xaa\xbb'
    HEADER_FORMAT = '!HBBHIHHI'
    HEADER_SIZE = struct.calcsize(HEADER_FORMAT)
    MAX_ZLIB_DECOMPRESSED_SIZE = 1024 * 1024

    def __init__(self, config: Config):
        self.config = config
        self.buffer = bytearray()
        self.stats = Stats()
        self.expected_sequence_numbers = {}

    def feed(self, data: bytes) -> Iterator[Event]:
        """Feed data into the decoder."""
        self.buffer.extend(data)
        while len(self.buffer) >= self.HEADER_SIZE:
            if self.buffer[:2] != self.SYNC_MARKER:
                index = self.buffer.find(self.SYNC_MARKER, 1)
                if index == -1:
                    break
                self.buffer = self.buffer[index:]
            else:
                try:
                    header = struct.unpack_from(self.HEADER_FORMAT, self.buffer, 0)
                    sync_marker, version, flags, stream_id, sequence_number, payload_length, compressed_flag, crc32 = header
                    if sync_marker != self.SYNC_MARKER:
                        raise FrameError('Invalid sync marker')
                    if version not in (1,):
                        raise VersionError(f'Unknown version: {version}')
                    if len(self.buffer) < self.HEADER_SIZE + payload_length:
                        break
                    payload = self.buffer[self.HEADER_SIZE:self.HEADER_SIZE + payload_length]
                    if compressed_flag:
                        try:
                            payload = zlib.decompress(payload)
                            if len(payload) > self.MAX_ZLIB_DECOMPRESSED_SIZE:
                                raise PayloadError('Decompressed payload too large')
                        except (zlib.error, MemoryError):
                            raise PayloadError('Zlib decompression failed')
                    calculated_crc32 = zlib.crc32(self.buffer[:self.HEADER_SIZE + payload_length]) & 4294967295
                    if calculated_crc32 != crc32:
                        raise CrcError('CRC mismatch')
                    if stream_id not in self.expected_sequence_numbers:
                        self.expected_sequence_numbers[stream_id] = sequence_number - 1
                    expected_sequence_number = self.expected_sequence_numbers[stream_id]
                    if sequence_number < expected_sequence_number:
                        raise SequenceError(f'Duplicate frame: {sequence_number}')
                    elif sequence_number > expected_sequence_number + 1:
                        self.stats.rejected_frames += 1
                        yield Event(stream_id, sequence_number, b'')
                        for seq_num in range(expected_sequence_number + 1, sequence_number):
                            self.expected_sequence_numbers[stream_id] = seq_num
                    else:
                        self.expected_sequence_numbers[stream_id] = sequence_number
                        self.stats.decoded_frames += 1
                        yield Event(stream_id, sequence_number, payload)
                except FrameError as e:
                    self.stats.rejected_frames += 1
                    yield Event(0, 0, b'')
                finally:
                    self.buffer = self.buffer[self.HEADER_SIZE + payload_length:]

    def drain(self) -> Iterator[Event]:
        """Drain any remaining frames in the buffer."""
        while len(self.buffer) >= self.HEADER_SIZE:
            try:
                yield from self.feed(b'')
            except StopIteration:
                break

    def get_stats(self) -> Stats:
        """Get decoder statistics."""
        return self.stats
